    if (closingBalances == null || closingBalances.isEmpty()) {
        throw new IllegalArgumentException("closingBalances must contain at least one element");
    }
    double sum = 0.0;
    int count = closingBalances.size();
    for (Double b : closingBalances) {
        if (b == null) {
            throw new IllegalArgumentException("closingBalances contains null value");
        }
        sum += b;
    }
    double average = sum / count;
    try {
        return new java.math.BigDecimal(average).setScale(2, java.math.RoundingMode.HALF_UP).doubleValue();
