    }
}

public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0) {
        throw new IllegalArgumentException("Start year must be positive.");
    }
    if (N <= 0) {
        throw new IllegalArgumentException("N must be positive.");
    }

    int count = 0;
    int year = Y;

    while (true) {
        // Check leap year according to Gregorian calendar rules
        boolean isLeap = (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
        if (isLeap) {
            count++;
            if (count == N) {
                return year;
            }
        }

        // Prevent integer overflow
        if (year == Integer.MAX_VALUE) {
            throw new RuntimeException("Reached maximum year limit without finding the Nth leap year.");
        }

        year++;
    }
}

