    }
    return null; // Should never be reached given problem constraints
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int remove = (int) Math.floor(n * 0.05);
    if (remove * 2 >= n) {
        // If removal would discard all elements or more, return 0
        return 0.0;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    double sum = 0.0;
    for (int i = remove; i < n - remove; i++) {
        sum += sorted[i];
    }
    return sum / (n - 2 * remove);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false; // division by zero or negative divisor is not supported
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int value : arr) {
        int rem = ((value % k) + k) % k; // ensure non-negative remainder
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check remainder k/2 when k is even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For all other remainders, freq[r] must equal freq[k - r]
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r > complement) {
            continue; // already checked pair when r was smaller
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] edge : edges) {
            if (edge == null || edge.length != 2) {
                throw new IllegalArgumentException("Each edge must contain exactly two vertices.");
            }
            int u = edge[0], v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Edge vertices out of bounds.");
            }
            graph[u].add(v);
            graph[v].add(u);
        }
    }
    // DFS to compute required time
    int[] total = {0};
    boolean[] visited = new boolean[n];

    java.util.function.Function<Integer, Boolean> dfs = new java.util.function.Function<Integer, Boolean>() {
        @Override
        public Boolean apply(Integer node) {
            visited[node] = true;
            boolean hasInSubtree = hasApple[node];
            for (int nei : graph[node]) {
                if (!visited[nei]) {
                    boolean childHasApple = apply(nei);
                    if (childHasApple) {
                        total[0] += 2; // travel to child and back
                        hasInSubtree = true;
                    }
                }
            }
            return hasInSubtree;
        }
    };

    dfs.apply(0);

    // If root has no apple and no necessary edges, total will be 0
    return total[0];
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("String must contain only lowercase letters a-z");
        }
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // ascending pass
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // descending pass
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    // dp[k][s] indicates whether a subset of size k with sum s is attainable
    // We only need sizes up to n/2 due to symmetry
    int maxK = n / 2;
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k descending to avoid reuse
        for (int k = Math.min(maxK, n - 1); k >= 1; k--) {
            for (int s = totalSum; s >= num; s--) {
                if (dp[k - 1][s - num]) {
                    dp[k][s] = true;
                }
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) {
            continue;
        }
        int target = (int) (prod / n);
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return Math.min(dp[n], dp[n - 1]);
}

public int uniqueMorseRepresentations(String[] words) {
