public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    if (s.length() < k) {
        return false;
    }
    // Prevent shifting by 31 or more bits which would cause overflow
    if (k >= 31) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int count = 0;
    int mask = totalCodes - 1;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
        int bit = s.charAt(i) - '0';
        current = ((current << 1) & mask) | bit;
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                if (count == totalCodes) {
                    return true;
                }
            }
        }
    }
    return count == totalCodes;
}

