public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int need = 0; // number of '(' needed to match current ')'
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            need++;
        } else if (c == ')') {
            if (need > 0) {
                need--;
            } else {
                // Need an extra '(' before this ')'
                insertions++;
            }
        } else {
            // Defensive: input should only contain '(' and ')'
            throw new IllegalArgumentException("Invalid character in input: " + c);
        }
    }
    // After processing all chars, any remaining unmatched '(' require ')'
    return insertions + need;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    long result;
    if ((n & 1) == 0) {
        long half = n / 2L;
        result = half * half;
    } else {
        long left = (n - 1L) / 2L;
        long right = (n + 1L) / 2L;
        result = left * right;
    }
    return (int) result;
}

