public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = nums[0];
    long curMax = nums[0];
    long minSum = nums[0];
    long curMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        curMax = Math.max(val, curMax + val);
        maxSum = Math.max(maxSum, curMax);
        curMin = Math.min(val, curMin + val);
        minSum = Math.min(minSum, curMin);
    }
    long absMax = Math.abs(maxSum);
    long absMin = Math.abs(minSum);
    long result = Math.max(absMax, absMin);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // enough for int range
    fib[0] = 1;
    fib[1] = 1;
    int countFib = 2;
    while (true) {
        int next = fib[countFib - 1] + fib[countFib - 2];
        if (next > k) {
            break;
        }
        fib[countFib++] = next;
    }
    int result = 0;
    int remaining = k;
    // Greedy: pick largest Fibonacci number <= remaining
    for (int i = countFib - 1; i >= 0; i--) {
        if (remaining >= fib[i]) {
            remaining -= fib[i];
            result++;
            if (remaining == 0) {
                break;
            }
        }
    }
    return result;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    int idx = k - small.size();          // 1‑based index in 'large' reversed
    return large.get(large.size() - idx);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int n = stack.length();
        if (n > 0) {
            char last = stack.charAt(n - 1);
            // In ASCII, a lowercase and its uppercase differ by 32.
            if ((last ^ c) == 32 && Character.toLowerCase(last) == Character.toLowerCase(c)) {
                stack.deleteCharAt(n - 1); // Remove the pair
                continue;
            }
        }
        stack.append(c); // Push current character
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int[] best = {0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer,Integer>() {
        @Override
        public void accept(Integer idx, Integer cnt) {
            if (idx == n) {
                if (cnt > best[0]) best[0] = cnt;
                return;
            }
            // Prune if even splitting every remaining character cannot surpass current best
            if (cnt + (n - idx) <= best[0]) return;
            for (int end = idx + 1; end <= n; end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    accept(end, cnt + 1);
                    used.remove(sub);
                }
            }
        }
    };
    dfs.accept(0, 0);
    return best[0];
}

