public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update bits that have appeared twice
        twos |= ones & num;
        // Update bits that have appeared once
        ones ^= num;
        // Bits that have appeared three times should be reset in both ones and twos
        int commonMask = ones & twos;
        ones &= ~commonMask;
        twos &= ~commonMask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high || high < 0) {
        return result;
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        if (i > high) break;
        queue.offer((long) i);
        if (i >= low) {
            result.add(i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num == 0) {
            continue; // skip expanding 0 to avoid leading zeros
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    // If n is negative or zero, no ones appear
    if (n <= 0) {
        return 0;
    }

    long count = 0;
    long number = n;

    for (long factor = 1; factor <= number; factor *= 10) {
        // digit at the current position
        long cur = (number / factor) % 10;
        // higher part (more significant digits)
        long higher = number / (factor * 10);
        // lower part (less significant digits)
        long lower = number - (number / factor) * factor;

        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }

    return (int) count;
}

