}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) return 0;
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) return 0;

    int[][] horiz = new int[m][n];
    int[][] vert  = new int[m][n];
    int[][] diag  = new int[m][n];
    int[][] anti  = new int[m][n];

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        if (mat[i] == null) continue; // handle ragged rows
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) continue; // treat any non-1 as 0

            horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
            vert[i][j]  = (i > 0 ? vert[i - 1][j] : 0) + 1;
            diag[i][j]  = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
            anti[i][j]  = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;

            int currentMax = Math.max(
                Math.max(horiz[i][j], vert[i][j]),
                Math.max(diag[i][j], anti[i][j])
            );
            if (currentMax > maxLen) maxLen = currentMax;
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle special case 0 directly
    if (n == 0) {
        return "0";
    }

    long value = n;          // convert to long to avoid overflow on abs
    boolean negative = value < 0;
    long absValue = negative ? -value : value;

    StringBuilder sb = new StringBuilder();
    int digitCount = 0;

    while (absValue > 0) {
        long digit = absValue % 10;
        sb.append((char) ('0' + digit));
        absValue /= 10;
        digitCount++;

        // Insert dot after every three digits, unless it's the last group
        if (digitCount % 3 == 0 && absValue != 0) {
            sb.append('.');
        }
    }

    // If number was negative, prepend '-'
    if (negative) {
        sb.append('-');
    }

    // Reverse to get the correct order
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int allMask = (1 << n) - 1;
    // Precompute adjacency compatibility
    boolean[][] canAdj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            canAdj[i][j] = (sqrt * sqrt == sum);
        }
    }
    java.util.HashMap<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.Function<java.util.AbstractMap.SimpleEntry<Integer, Integer>, Integer> dfs = new java.util.function.Function<>() {
        @Override
        public Integer apply(java.util.AbstractMap.SimpleEntry<Integer, Integer> state) {
            int mask = state.getKey();
            int last = state.getValue();
            if (mask == allMask) return 1;
            long key = (((long) mask) << 8) | last;
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            int count = 0;
            java.util.HashSet<Integer> seen = new java.util.HashSet<>();
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                if (seen.contains(A[nxt])) continue;
                if (last == -1 || canAdj[last][nxt]) {
                    count += dfs.apply(new java.util.AbstractMap.SimpleEntry<>(mask | (1 << nxt), nxt));
                }
                seen.add(A[nxt]);
            }
            memo.put(key, count);
            return count;
        }
    };
    int result = 0;
    for (int start = 0; start < n; start++) {
        result += dfs.apply(new java.util.AbstractMap.SimpleEntry<>(1 << start, start));
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top != -1 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = (int) area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int maxSize = Math.min(m, n);
    for (int s = 0; s <= m + n - 2; s++) {
        int[] buffer = new int[maxSize];
        int count = 0;
        for (int i = 0; i < m; i++) {
            int j = s - i;
            if (j >= 0 && j < n) {
                buffer[count++] = mat[i][j];
            }
        }
        if (s % 2 == 0) {
            for (int k = count - 1; k >= 0; k--) {
                result[idx++] = buffer[k];
            }
        } else {
            for (int k = 0; k < count; k++) {
                result[idx++] = buffer[k];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1; // Input should be positive
    }
    String s = Integer.toString(n);
    char[] arr = s.toCharArray();
    int len = arr.length;

    // Find the pivot index where arr[i] < arr[i + 1]
    int i = len - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // No larger permutation exists
    }

    // Find the rightmost element greater than pivot
    int j = len - 1;
    while (j > i && arr[j] <= arr[i]) {
        j--;
    }

    // Swap pivot with this element
    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;

    // Reverse the suffix starting at i + 1
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }

    // Convert back to number with overflow check
    long result = 0;
    for (int k = 0; k < len; k++) {
        result = result * 10 + (arr[k] - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // Result doesn't fit in int
        }
    }

    return (int) result;
}

